SELECT p.id AS pid, CASE WHEN e.observed_at <= p.opened_at + INTERVAL 2 SECOND THEN 'ENTRY' ELSE 'EXIT' END AS phase, e.id, e.symbol, e.observed_at, e.price, e.delivery_status, e.outcome_reason, e.source, e.created_at FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol = p.symbol AND (e.observed_at BETWEEN p.opened_at - INTERVAL 20 SECOND AND p.opened_at + INTERVAL 2 SECOND OR e.observed_at BETWEEN p.closed_at - INTERVAL 45 SECOND AND p.closed_at + INTERVAL 5 SECOND) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, e.observed_at LIMIT 400;